import unittest
from audio.service import duration

class Audio(unittest.TestCase):
    def test_frames(self):
        self.assertEqual(duration(bytes(32000),8000,2,16),1.0)
        self.assertEqual(duration(bytes(24000),8000,1,24),1.0)
        self.assertEqual(duration(bytes(4),8,1,8),0.5)
        self.assertEqual(duration(b'',48000,2,32),0)
    def test_invalid(self):
        with self.assertRaises(ValueError): duration(bytes(3),8000,2,16)
        for rate,channels,bits in [(0,2,16),(8000,0,16),(-2,1,8),(8000,2,12),(1.5,1,8)]:
            with self.assertRaises(ValueError): duration(b'',rate,channels,bits)

if __name__ == '__main__':
    unittest.main()

